    <Canvas pointerEvents="none" accessibilityLabel={accessibilityLabel} style={{ position: "absolute", left: 0, top: 0, width: width + 256, height: 184 + barHeight + 25 }}>
      <Fill><Shader source={flameEffect} uniforms={uniforms} /></Fill>
    </Canvas>
